      if (ctx.direction === "backward") {
        const encoded = def.innerType._zod.run(payload, ctx);
        if (def.skipEncoding === undefined || def.skipEncoding === false) return encoded;
        if (encoded instanceof Promise) {
          return encoded.then((encoded) => handleDefaultEncodeResult(encoded, def, ctx));
        }
