function handleDefaultEncodeResult(payload: ParsePayload, def: $ZodDefaultDef, ctx: ParseContextInternal) {
  if (payload.issues.length) return payload;

  const finish = (encodedDefault: ParsePayload) => {
    if (encodedDefault.issues.length) return payload;
    const option = def.skipEncoding!;
    let matches: boolean | Promise<boolean>;
    if (typeof option === "function") {
